mapper.select:
select *
from (select *
from (select A.*, rownum rn
from (SELECT  ,i.job_desc jobDesc
from xxl_job_operate_log t left join xxl_job_info i on t.job_id = i.id


        AND t.username like CONCAT(CONCAT('%', #{username}), '%')


        AND i.job_desc like CONCAT(CONCAT('%', #{jobDesc}), '%')


        AND t.operate_type = #{operateType}


        AND t.operate_time  >=  #{operateTimeStart}


        AND t.operate_time  <=  #{operateTimeEnd}


ORDER BY t.operate_time DESC) A)
where rn > #{offset}) B
	where rn < #{offset}+ #{pagesize}

SELECT count(1) FROM xxl_job_operate_log t left join xxl_job_info i on t.job_id = i.id


        AND t.username like CONCAT(CONCAT('%', #{username}), '%')


        AND i.job_desc like CONCAT(CONCAT('%', #{jobDesc}), '%')


        AND t.operate_type = #{operateType}


        AND t.operate_time  >=  #{operateTimeStart}


        AND t.operate_time  <=  #{operateTimeEnd}
